const ALLOWED = ["facebook","instagram","linkedin","twitter","threads","bluesky","tiktok","youtube"];
function parsePlatforms(raw) {
  const list = (Array.isArray(raw) ? raw : String(raw || '').split(','))
    .map((p) => String(p).trim().toLowerCase())
    .filter(Boolean)
    .map((p) => (p === 'x' ? 'twitter' : p));
  const unknown = list.filter((p) => !ALLOWED.includes(p));
  if (unknown.length) throw new Error('Socialync cannot post to: ' + unknown.join(', ') + '. Use: ' + ALLOWED.join(', ') + '.');
  if (!list.length) throw new Error('Set at least one platform in the Settings node.');
  return [...new Set(list)];
}
// '2026-11-12 09:30' is read in the Settings time zone. A value with Z or an offset is used as written.
function parseWhen(text, zone) {
  const s = String(text || '').trim();
  if (!s) return null;
  if (/([zZ]|[+-]\d{2}:?\d{2})$/.test(s)) {
    const d = new Date(s);
    return isNaN(d.getTime()) ? null : d;
  }
  const m = s.match(/^(\d{4})-(\d{2})-(\d{2})(?:[ T](\d{1,2}):(\d{2}))?/);
  if (!m) return null;
  const [y, mo, d] = m.slice(1, 4).map(Number);
  const h = m[4] === undefined ? 9 : Number(m[4]);
  const mi = m[5] === undefined ? 0 : Number(m[5]);
  const guess = Date.UTC(y, mo - 1, d, h, mi);
  const offsetAt = (t) => {
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone: zone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit',
    }).formatToParts(new Date(t));
    const v = {};
    for (const p of parts) if (p.type !== 'literal') v[p.type] = Number(p.value);
    return Date.UTC(v.year, v.month - 1, v.day, v.hour, v.minute, v.second) - t;
  };
  let utc = guess - offsetAt(guess);
  utc = guess - offsetAt(utc);
  return new Date(utc);
}
// Socialync accepts 1 to 255 letters, digits and _ . : - in an Idempotency Key.
function safeKey(prefix, value) {
  return (prefix + ':' + String(value)).replace(/[^A-Za-z0-9_.:-]/g, '-').slice(0, 200);
}
const s = $input.item.json;
const caption = String(s.Caption || '').trim();
if (!caption) throw new Error('The caption is empty.');
const platforms = parsePlatforms(s.Platforms).filter((p) => !['tiktok', 'youtube'].includes(p));
if (!platforms.length) throw new Error('Choose at least one platform.');
if (platforms.includes('instagram') && !($input.item.binary && Object.keys($input.item.binary).length)) throw new Error('Instagram needs a picture. Add one or untick Instagram.');
const earliest = Date.now() + Math.max(5, Number(s.publishDelayMinutes) || 10) * 60000;
const rawWhen = String(s['Publish at (like 2026-11-12 09:30)'] || '').trim();
let when = null;
if (rawWhen) {
  when = parseWhen(rawWhen, s.timezone || 'UTC');
  if (!when) throw new Error('The time must look like 2026-11-12 09:30.');
}
const scheduledAt = new Date(Math.max(earliest, when ? when.getTime() : 0)).toISOString();
return { json: { post: {
  profileId: String(s.profileId || '').trim(),
  platforms,
  caption,
  scheduledAt,
  idempotencyKey: safeKey('form', $execution.id),
} }, binary: $input.item.binary };
